<?php
require "config.php"; require "auth.php"; requireAdmin();
if ($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['delete_user'])) { $id=(int)$_POST['delete_user']; if($id !== (int)$_SESSION['user_id']) { $st=$pdo->prepare("DELETE FROM users WHERE user_id=? AND role='student'"); $st->execute([$id]); } header('Location: admin_students.php'); exit; }
$students=$pdo->query("SELECT u.user_id,u.username,u.email,u.created_at,COUNT(r.result_id) attempts,COALESCE(SUM(r.score),0) total_score,COALESCE(AVG(r.percentage),0) avg_percentage FROM users u LEFT JOIN results r ON r.user_id=u.user_id WHERE u.role='student' GROUP BY u.user_id ORDER BY u.user_id DESC")->fetchAll();
?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Students - Admin</title><link rel="stylesheet" href="style.css"></head><body><nav class="navbar"><div class="brand">QuizMaster Admin</div><div class="nav-right"><a class="btn small" href="admin.php">Admin Home</a><a class="btn small" href="logout.php">Logout</a></div></nav><main class="container"><h1>All Students</h1><div class="card"><div class="table-wrap"><table><tr><th>ID</th><th>Username</th><th>Email</th><th>Attempts</th><th>Avg %</th><th>Joined</th><th>Details</th><th>Delete</th></tr><?php foreach($students as $s): ?><tr><td><?= (int)$s['user_id'] ?></td><td><?= htmlspecialchars($s['username']) ?></td><td><?= htmlspecialchars($s['email']) ?></td><td><?= (int)$s['attempts'] ?></td><td><?= number_format((float)$s['avg_percentage'],1) ?>%</td><td><?= htmlspecialchars($s['created_at']) ?></td><td><a class="btn small" href="admin_student.php?id=<?= (int)$s['user_id'] ?>">View History</a></td><td><form method="post" onsubmit="return confirm('Delete this student and all their results?');"><input type="hidden" name="delete_user" value="<?= (int)$s['user_id'] ?>"><button class="btn small" type="submit">Delete</button></form></td></tr><?php endforeach; ?></table></div></div></main></body></html>
